import { createRequire } from "node:module";
import assert from "node:assert/strict";
const { chromium } = createRequire(import.meta.url)("playwright");
const [base, executablePath, token] = process.argv.slice(2);
const browser = await chromium.launch({ executablePath, headless: true });
const context = await browser.newContext();
await context.addInitScript(() => {
  for (const [key, ms] of Object.entries({ ask: 250, groom: 250, pulse: 250 }))
    localStorage.setItem("devkit.poll." + key, String(ms));
});

try {
  assert.equal((await context.request.post(base + "/api/login", { data: { token } })).status(), 200);
  const page = await context.newPage();
  const errors = [];
  const sent = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  page.on("request", (r) => { if (r.method() === "POST" && r.url().endsWith("/say")) sent.push(r.postDataJSON()); });
  await page.goto(base + "/#demo/chat/aa144600-1111-4111-8111-111111111111");
  const active = page.locator(".caskpick:not(:disabled)");
  const readonly = page.locator(".caskpick:disabled");
  const ta = page.locator("textarea.csay");
  const send = page.locator(".csend");
  await page.locator(".caskpick").first().waitFor();
  assert.equal(await page.locator("input.caskpick[type=checkbox]").count(), 3, "галочки должны быть видимыми native checkbox");
  for (let i = 0; i < 3; i++) assert.equal(await active.nth(i).isChecked(), i !== 1, "отмечен только рекомендованный поднабор");
  const noPin = async () => assert.equal(await page.locator(".attach-selection,.selection-preview,.selection-attachment").count(), 0, "служебного выбора нет в composer и ленте");
  await noPin();
  await active.first().locator("..").click();
  assert.equal(await active.first().isChecked(), false, "текст строки переключает checkbox");
  await active.first().locator("..").click();
  assert.equal(await active.first().isChecked(), true);
  await page.getByRole("button", { name: "По рекомендации", exact: true }).waitFor();
  if (process.env.DASHBOARD_CHOICE_SCREENSHOT) {
    await active.first().evaluate((n) => n.scrollIntoView({ block: "center" }));
    await page.screenshot({ path: process.env.DASHBOARD_CHOICE_SCREENSHOT.replace("mobile", "desktop") });
    await page.setViewportSize({ width: 320, height: 800 });
    await active.first().evaluate((n) => n.scrollIntoView({ block: "center" }));
    await page.screenshot({ path: process.env.DASHBOARD_CHOICE_SCREENSHOT });
    await page.setViewportSize({ width: 1280, height: 720 });
  }
  assert.equal(await send.locator(".choice-border").count(), 1, "у рамки есть отдельный слой бегунка");
  const style = await send.evaluate((n) => { const s = getComputedStyle(n); const a = getComputedStyle(n.querySelector(".choice-border"), "::before"); return [s.borderTopWidth, a.animationDuration, a.animationTimingFunction, a.animationIterationCount]; });
  assert.deepEqual(style, ["3px", "2.8s", "linear", "infinite"]);
  const frameProperties = await send.evaluate((n) => n.getAnimations({ subtree: true }).flatMap((a) => a.effect.getKeyframes()).flatMap(Object.keys));
  assert.ok(frameProperties.includes("transform"), "бегунок вращается отдельным слоем");
  assert.ok(frameProperties.every((name) => ["offset", "computedOffset", "easing", "composite", "transform", "opacity"].includes(name)), "анимация меняет только свойства композитора");
  await page.emulateMedia({ reducedMotion: "reduce" });
  assert.equal(await send.evaluate((n) => getComputedStyle(n.querySelector(".choice-border"), "::before").animationName), "none");
  await page.emulateMedia({ reducedMotion: "no-preference" });
  const submit = async (name, status = 200) => {
    const response = page.waitForResponse((r) => r.url().endsWith("/say") && r.request().method() === "POST");
    await page.getByRole("button", { name, exact: true }).click();
    assert.equal((await response).status(), status);
    await page.waitForFunction(() => {
      const button = document.querySelector(".csend");
      return button && !button.disabled;
    });
  };
  await submit("По рекомендации");
  assert.equal(sent.at(-1).text, "");
  assert.deepEqual(sent.at(-1).selection.questions[0].ids, ["СЦ-1", "СЦ-3"]);
  await page.locator(".chatfeed .msg.me .bb .md p", { hasText: "По рекомендации" }).first().waitFor();
  assert.equal(await page.locator(".chatfeed .msg.me .bb .md").filter({ hasText: /^\s*$/ }).count(), 0, "пустых пузырей ответа нет");
  await readonly.first().waitFor();
  assert.equal(await active.count(), 0);
  await page.reload();
  await readonly.first().waitFor();
  assert.equal(await readonly.count(), 3);
  assert.equal(await readonly.nth(1).isChecked(), false);
  await page.locator(".chatfeed .msg.me .bb .md p", { hasText: "По рекомендации" }).first().waitFor();
  await noPin();
  await context.request.get(base + "/__scenario?do=fresh");
  await active.first().waitFor();
  for (let i = 0; i < 3; i++) await active.nth(i).uncheck();
  await submit("Мой вариант");
  assert.deepEqual(sent.at(-1).selection.questions[0].ids, []);
  await page.locator(".chatfeed .msg.me .bb .md p", { hasText: "ничего" }).first().waitFor();
  await page.reload();
  await readonly.first().waitFor();
  assert.ok(await readonly.count() >= 3);
  assert.ok(await page.locator(".caskpick:disabled:not(:checked)").count() >= 3);
  await page.locator(".chatfeed .msg.me .bb .md p", { hasText: "ничего" }).first().waitFor();
  await context.request.get(base + "/__scenario?do=fresh");
  await active.first().waitFor();
  await active.first().check();
  const own = '  пояснение\nплюс, минус; "слова, как есть"  ';
  await ta.fill(own);
  await page.getByRole("button", { name: "Выбрать и обсудить", exact: true }).waitFor();
  await page.route("**/say", (route) => route.abort("failed"));
  const failed = page.waitForEvent("requestfailed", { predicate: (r) => r.url().endsWith("/say") });
  await send.click();
  await failed;
  await page.getByText("не ушло, дожимаю", { exact: true }).waitFor();
  assert.equal(await active.first().isChecked(), true, "неудачная отправка сохраняет выбор");
  const attempted = sent.at(-1);
  assert.equal(attempted.text, own);
  assert.deepEqual(attempted.selection.questions[0].ids, ["СЦ-1"]);
  await page.unroute("**/say");
  const retried = page.waitForResponse((r) => r.url().endsWith("/say") && r.request().method() === "POST");
  await page.reload();
  assert.equal((await retried).status(), 200);
  assert.deepEqual(sent.at(-1), attempted);
  await readonly.first().waitFor();
  await page.locator(".chatfeed .msg.me .bb .md p", { hasText: "пояснение" }).first().waitFor();
  await noPin();
  await context.request.get(base + "/__scenario?do=next-real");
  const radio = page.locator("input.caskpick[type=radio]:not(:disabled)");
  await radio.first().waitFor();
  const firstRadioAsk = (await (await context.request.get(base + "/api/projects/demo/chats/aa144600-1111-4111-8111-111111111111/ask")).json()).ask;
  assert.equal(await radio.first().isChecked(), true, "обычная рекомендация выбрана сразу");
  await radio.first().click();
  assert.equal(await radio.first().isChecked(), true, "повторное нажатие radio сохраняет выбор");
  await radio.nth(1).locator("..").click();
  assert.equal(await radio.first().isChecked(), false);
  assert.equal(await radio.nth(1).isChecked(), true);
  const imageUpload = page.waitForResponse((r) => r.url().endsWith("/shot") && r.request().method() === "POST");
  await ta.evaluate((n) => {
    const dt = new DataTransfer();
    const png = Uint8Array.from(atob("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jK1cAAAAASUVORK5CYII="), (c) => c.charCodeAt(0));
    dt.items.add(new File([png], "test.png", { type: "image/png" }));
    n.dispatchEvent(new ClipboardEvent("paste", { clipboardData: dt, bubbles: true, cancelable: true }));
  });
  assert.equal((await imageUpload).status(), 200);
  const clipUpload = page.waitForResponse((r) => r.url().endsWith("/clip") && r.request().method() === "POST");
  await ta.evaluate((n) => {
    const dt = new DataTransfer();
    dt.setData("text/plain", "фрагмент ".repeat(600));
    n.dispatchEvent(new ClipboardEvent("paste", { clipboardData: dt, bubbles: true, cancelable: true }));
  });
  assert.equal((await clipUpload).status(), 200);
  await submit("Мой вариант");
  assert.match(sent.at(-1).text, /<screenshot file="/);
  assert.match(sent.at(-1).text, /<fragment file="/);
  assert.deepEqual(sent.at(-1).selection.questions.map((q) => [q.fork, q.ids]), [["доставка", ["2"]]]);
  await page.reload();
  await page.locator("input.caskpick[type=radio]:disabled").first().waitFor();
  assert.equal(await page.locator("input.caskpick[type=radio]:disabled").nth(0).isChecked(), false);
  assert.equal(await page.locator("input.caskpick[type=radio]:disabled").nth(1).isChecked(), true);
  await noPin();
  const oldRadioName = await page.locator("input.caskpick[type=radio]:disabled").nth(1).getAttribute("name");
  const nextRadioAsk = structuredClone(firstRadioAsk);
  nextRadioAsk.since += 1;

  await page.route("**/ask", (route) => route.fulfill({ json: { ask: nextRadioAsk } }));
  await page.reload();
  await radio.first().waitFor();
  assert.notEqual(await radio.first().getAttribute("name"), oldRadioName);
  await radio.nth(1).locator("..").click();
  assert.equal(await page.locator("input.caskpick[type=radio]:disabled").nth(1).isChecked(), true, "новая radio group сохраняет старый выбор");
  await page.route("**/say", (route) => route.fulfill({ json: { way: "ask" } }));
  await page.evaluate(() => {
    window.choiceResponseGate = {};
    const text = Response.prototype.text;
    Response.prototype.text = async function (...args) {
      const body = await text.apply(this, args);
      if (this.url.endsWith("/say")) {
        Response.prototype.text = text;
        window.choiceResponseGate.blocked = true;
        await new Promise((resolve) => { window.choiceResponseGate.release = resolve; });
      }
      return body;
    };
  });
  let submitted = false;
  const sending = submit("Мой вариант").then(() => { submitted = true; });
  await page.waitForFunction(() => window.choiceResponseGate.blocked);
  try {
    assert.equal(await radio.count(), 2, "до обработки ответа выбор остаётся активным");
    assert.equal(await send.isDisabled(), true, "отправка ждёт обработки ответа");
    assert.equal(submitted, false, "submit не завершается до обработки тела ответа");
  } finally {
    await page.evaluate(() => window.choiceResponseGate.release());
  }
  await sending;
  assert.equal(await radio.count(), 0, "повтор того же выбора подтверждает новый экземпляр вопроса");
  await page.unroute("**/say");
  await page.setViewportSize({ width: 320, height: 800 });
  const layout = await page.evaluate(() => {
    const box = document.querySelector(".cbox").getBoundingClientRect();
    const msg = document.querySelector(".chatfeed .msg").getBoundingClientRect();
    const button = document.querySelector(".csend").getBoundingClientRect();
    const toolbar = document.querySelector(".crow .cmodel").getBoundingClientRect();
    return { left: box.left - msg.left, overflow: document.documentElement.scrollWidth > innerWidth, controlsOverflow: [...document.querySelectorAll(".cbox button,.cbox select")].filter((n) => n.getClientRects().length > 0).some((n) => n.getBoundingClientRect().right > box.right || n.getBoundingClientRect().left < box.left), button: button.toJSON(), toolbar: toolbar.toJSON(), box: box.toJSON() };
  });
  assert.ok(Math.abs(layout.left) <= 1, "composer выровнен по внешнему краю сообщений: " + JSON.stringify(layout));
  assert.equal(layout.overflow, false);
  assert.equal(layout.controlsOverflow, false, "все кнопки и выбор модели остаются внутри composer");
  assert.ok(layout.button.top >= layout.toolbar.bottom);
  assert.ok(layout.button.width > layout.box.width - 34);
  if (process.env.DASHBOARD_CHOICE_SCREENSHOT) await page.screenshot({ path: process.env.DASHBOARD_CHOICE_SCREENSHOT.replace("mobile", "history") });
  await page.unroute("**/ask");
  await page.reload();
  await ta.fill("обычная реплика");
  await page.getByRole("button", { name: "Отправить", exact: true }).waitFor();
  await page.route("**/say", (route) => route.fulfill({ json: { way: "ask" } }));
  await submit("Отправить");
  assert.equal(sent.at(-1).text, "обычная реплика");
  assert.equal(sent.at(-1).selection, undefined);
  await page.unroute("**/say");
  await context.request.get(base + "/__scenario?do=fresh");
  await page.locator("input.caskpick[type=checkbox]:not(:disabled)").first().waitFor();
  await ta.fill("текст после отказа");
  await context.request.get(base + "/__scenario?do=reorder");
  const before = await (await context.request.get(base + "/__scenario")).json();
  await submit("Выбрать и обсудить", 400);
  const after = await (await context.request.get(base + "/__scenario")).json();
  assert.deepEqual(after, before, "старый snapshot не изменяет документ и ожидание");
  await context.request.get(base + "/__scenario?do=ordinary");
  await page.reload();
  await radio.nth(3).waitFor();
  assert.equal(await radio.count(), 4);
  await radio.nth(1).click();
  await radio.nth(2).click();
  const exact = '  пояснение к сроку\nи выводу  ';
  await ta.fill(exact);
  await submit("Выбрать и обсудить");
  assert.equal(sent.at(-1).text, exact);
  assert.deepEqual(sent.at(-1).selection.questions.filter((q) => q.fork !== "сценарии").map((q) => [q.fork, q.ids]), [["срок", ["2"]], ["вывод", ["1"]]]);
  const state = await (await context.request.get(base + "/__scenario")).json();
  assert.match(state.doc, /решено человеком [\d-]+: 7 дней/);
  assert.match(state.doc, /решено человеком [\d-]+: полный: нужен/);
  await noPin();
  assert.deepEqual(errors, []);
  console.log(JSON.stringify({ sent: sent.length, native: true, emptyChoice: true, bubbleWords: true, retry: true, readonlyReload: true, mobile: true, noPin: true }));
} finally { await context.close(); await browser.close(); }
